using System.Text.Json;
using SysAdminAssistant.Core;
namespace SysAdminAssistant.Infrastructure;
public sealed class InvoiceSettings
{
    public bool Enabled{get;set;}public MailSettings Mailbox{get;set;}=new(){UnseenOnly=false,RequireSpfDkim=false};public int PollSeconds{get;set;}=300;public bool OnlyNew{get;set;}=true;public DateTime? StartFromUtc{get;set;}public string[] AllowedSenders{get;set;}=[];public List<InvoiceTemplate> Templates{get;set;}=[];
}
public sealed record InvoiceSettingsView(InvoiceSettings Settings,string Hash,string Status,bool OcrReady);
public sealed record InvoiceSettingsSave(InvoiceSettings Settings,string Password,string ExpectedHash);
public sealed record InvoiceHistory(DateTime Utc,string Message);
public sealed class InvoiceCursor{public string Source{get;set;}="";public uint Validity{get;set;}public uint LastUid{get;set;}public bool Ready{get;set;}}
public sealed class InvoiceSettingsStore(string directory)
{
    string PathName=>Path.Combine(directory,"invoice-settings.json");
    public InvoiceSettings Load()=>NetworkStore.Locked(PathName,()=>File.Exists(PathName)?JsonSerializer.Deserialize<InvoiceSettings>(File.ReadAllText(PathName),RemoteData.Json)??throw new InvalidDataException(global::SysAdminAssistant.Core.ProductText.Get("Пустые настройки счетов")):new());
    public InvoiceSettingsView View(){var s=Load();var hash=RemoteData.Hash(s);s.Mailbox.ProtectedPassword=s.Mailbox.ProtectedPassword.Length>0?"REMOTE":"";var history=History();return new(s,hash,history.LastOrDefault()?.Message??"Ещё не проверялось",File.Exists(Path.Combine(AppContext.BaseDirectory,"tessdata","rus.traineddata"))&&File.Exists(Path.Combine(AppContext.BaseDirectory,"tessdata","eng.traineddata")));}
    public void Save(InvoiceSettingsSave request){NetworkStore.Locked(PathName,()=>{var old=File.Exists(PathName)?JsonSerializer.Deserialize<InvoiceSettings>(File.ReadAllText(PathName),RemoteData.Json)!:new InvoiceSettings();if(RemoteData.Hash(old)!=request.ExpectedHash)throw new InvoiceConflictException(global::SysAdminAssistant.Core.ProductText.Get("Настройки счетов изменены. Откройте заново"));if(request.Password.Length>10000)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Слишком длинный пароль ящика"));Validate(request.Settings);var s=request.Settings;s.AllowedSenders=s.AllowedSenders.Select(x=>MimeKit.MailboxAddress.Parse(x).Address).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();foreach(var t in s.Templates){t.Sender=MimeKit.MailboxAddress.Parse(t.Sender).Address;t.BankAccount=t.BankAccount.Replace(" ","").Trim();t.BankCode=t.BankCode.Trim();t.TaxId=t.TaxId.Replace(" ","").Trim();}s.Mailbox.ProtectedPassword=request.Password.Length==0?StoredCredential.MailPassword(s.Mailbox,old.Mailbox):LocalSecret.Protect(request.Password);Atomic(PathName,s);return true;});}
    public static void Validate(InvoiceSettings s){if(s.Mailbox==null||s.Templates==null||s.AllowedSenders==null||s.PollSeconds is <30 or >3600||s.Templates.Count>100||s.AllowedSenders.Length>200)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Некорректные настройки счетов"));if(s.Mailbox.Host.Length>253||s.Mailbox.User.Length>200||s.Mailbox.Folder.Length>512)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Слишком длинные параметры ящика"));if(s.Enabled)MailAuthentication.Validate(s.Mailbox);if(s.Enabled&&(s.Mailbox.Host.Length==0||s.Mailbox.User.Length==0||s.Mailbox.Folder.Length==0||s.Mailbox.Port is <1 or >65535||!s.OnlyNew&&s.StartFromUtc==null))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Укажите ящик, папку и начало загрузки"));if(s.StartFromUtc>DateTime.UtcNow)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Начало загрузки не может быть в будущем"));if(s.Templates.Select(t=>t.Id).Distinct().Count()!=s.Templates.Count)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Повторяются шаблоны"));foreach(var t in s.Templates){if(t.Name.Length is <1 or >200||t.SubjectContains.Length>200||t.Supplier.Length>200||t.BankAccount.Length>100||t.BankCode.Length>100||t.TaxId.Length>100||t.Currency.Length!=3||!t.Currency.All(char.IsAsciiLetterUpper)||t.Sender.Length>200||!MimeKit.MailboxAddress.TryParse(t.Sender,out _)||t.Anchors.Count>12||t.Anchors.Any(x=>!new[]{"Supplier","TaxId","Kpp","Number","InvoiceDate","DueDate","Amount","Currency","BankAccount","BankCode","Correspondent"}.Contains(x.Key)||x.Value.Length>100)||t.DueDays is <0 or >365)throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Проверьте поля шаблона"));if(t.AutoCreate&&(t.Supplier.Length==0||t.BankAccount.Length==0||t.BankCode.Length==0))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Для автоматического добавления подтвердите поставщика и банковские реквизиты"));}foreach(var sender in s.AllowedSenders)if(!MimeKit.MailboxAddress.TryParse(sender,out _))throw new ArgumentException(global::SysAdminAssistant.Core.ProductText.Get("Укажите точные email отправителей"));}
    public static void Atomic<T>(string path,T value){var temp=path+"."+Guid.NewGuid().ToString("N")+".tmp";try{File.WriteAllText(temp,JsonSerializer.Serialize(value,RemoteData.Json));File.Move(temp,path,true);}finally{if(File.Exists(temp))File.Delete(temp);}}
    public T Cursor<T>(Func<InvoiceCursor,T> action){var p=Path.Combine(directory,"invoice-cursor.json");return NetworkStore.Locked(p,()=>{var s=File.Exists(p)?JsonSerializer.Deserialize<InvoiceCursor>(File.ReadAllText(p))!:new();var result=action(s);Atomic(p,s);return result;});}
    public void Log(string message){var p=Path.Combine(directory,"invoice-history.json");NetworkStore.Locked(p,()=>{var s=File.Exists(p)?JsonSerializer.Deserialize<List<InvoiceHistory>>(File.ReadAllText(p))??[]:[];s.Add(new(DateTime.UtcNow,message.Length>1000?message[..1000]:message));Atomic(p,s.TakeLast(1000).ToArray());return true;});}
    public InvoiceHistory[] History(){var p=Path.Combine(directory,"invoice-history.json");return NetworkStore.Locked(p,()=>File.Exists(p)?JsonSerializer.Deserialize<InvoiceHistory[]>(File.ReadAllText(p))??[]:[]);}
}
